private void SubTreeView_OnOnTreeNodeDoubleClick(object sender, ObjectEventArgs e)
	{
		if (!(e.Param is SubTreeNode { DisplayNameA: var displayNameA } subTreeNode))
		{
			return;
		}
		int startIndex = 0;
		int includedStringInfo;
		if (Popup.PlacementTarget == ExpressBox && Popup.IsOpen)
		{
			includedStringInfo = GetIncludedStringInfo(ExpressBox.Text, ExpressBox.CaretIndex, "[", "]", ref startIndex);
			if (includedStringInfo > 0)
			{
				ExpressBox.Select(startIndex, includedStringInfo);
				RemoveText();
			}
			InsertText($"<{displayNameA}>");
			return;
		}
		includedStringInfo = GetIncludedStringInfo(ExpressBox.Text, ExpressBox.CaretIndex, "<", ">", ref startIndex);
		if (includedStringInfo >= 0)
		{
			if (includedStringInfo > 0)
			{
				ExpressBox.Select(startIndex, includedStringInfo);
				RemoveText();
			}
			InsertText(displayNameA);
		}
		else
		{
			StringBuilder stringBuilder = new StringBuilder();
			object parentNode = subTreeNode.ParentNode;
			stringBuilder.Append($"{displayNameA}");
			while (parentNode is SubTreeNode subTreeNode2)
			{
				stringBuilder.Insert(0, $"{subTreeNode2.DisplayNameA}.");
				parentNode = subTreeNode2.ParentNode;
			}
			InsertText($"<{stringBuilder}>");
		}
		Popup.IsOpen = false;
	}

